using System.Text.Json; using CompanyManagement.Api.DTOs; using CompanyManagement.Api.Models; using CompanyManagement.Api.Repositories; using StackExchange.Redis;
namespace CompanyManagement.Api.Services;
public interface ICacheService { Task<T?> Get<T>(string key); Task Set<T>(string key,T value); Task Remove(params string[] keys); }
public class RedisCacheService(IConnectionMultiplexer redis, ILogger<RedisCacheService> log):ICacheService { readonly IDatabase _db=redis.GetDatabase(); public async Task<T?> Get<T>(string k){try {var v=await _db.StringGetAsync(k); log.LogInformation(v.HasValue?"Cache hit: {Key}":"Cache miss: {Key}",k); return v.HasValue?JsonSerializer.Deserialize<T>(v!):default;}catch(Exception e){log.LogWarning(e,"Redis no disponible; se usa base de datos");return default;}} public async Task Set<T>(string k,T v){try{await _db.StringSetAsync(k,JsonSerializer.Serialize(v),TimeSpan.FromMinutes(10));}catch(Exception e){log.LogWarning(e,"No se pudo guardar en Redis");}} public async Task Remove(params string[] k){try{await Task.WhenAll(k.Select(x=>_db.KeyDeleteAsync(x)));}catch(Exception e){log.LogWarning(e,"No se pudo invalidar Redis");}} }
public interface IClienteService { Task<List<ClienteDto>> All(); Task<ClienteDto?> Get(int id); Task<(ClienteDto? data,string? error)> Create(ClienteCreateDto dto); Task<(bool ok,string? error)> Update(int id,ClienteUpdateDto dto); Task<(bool ok,string? error)> Delete(int id); }
public class ClienteService(IClienteRepository repo,ICacheService cache):IClienteService { const string AllKey="clientes:all"; static ClienteDto Map(Cliente c)=>new(c.Id,c.Nombre,c.Email,c.FechaRegistro); public async Task<List<ClienteDto>> All(){var v=await cache.Get<List<ClienteDto>>(AllKey);if(v!=null)return v;v=(await repo.All()).Select(Map).ToList();await cache.Set(AllKey,v);return v;} public async Task<ClienteDto?> Get(int id){var key=$"clientes:{id}";var v=await cache.Get<ClienteDto>(key);if(v!=null)return v;var c=await repo.Get(id);if(c==null)return null;v=Map(c);await cache.Set(key,v);return v;} public async Task<(ClienteDto?,string?)> Create(ClienteCreateDto d){if(await repo.EmailExists(d.Email))return(null,"El email ya existe.");var c=new Cliente{Nombre=d.Nombre.Trim(),Email=d.Email.Trim().ToLowerInvariant(),FechaRegistro=d.FechaRegistro??DateTime.UtcNow};await repo.Add(c);await repo.Save();var v=Map(c);await cache.Remove(AllKey);return(v,null);} public async Task<(bool,string?)> Update(int id,ClienteUpdateDto d){var c=await repo.Get(id);if(c==null)return(false,"Cliente no encontrado.");if(await repo.EmailExists(d.Email,id))return(false,"El email ya existe.");c.Nombre=d.Nombre.Trim();c.Email=d.Email.Trim().ToLowerInvariant();if(d.FechaRegistro.HasValue)c.FechaRegistro=d.FechaRegistro.Value;await repo.Save();await cache.Remove(AllKey,$"clientes:{id}");return(true,null);} public async Task<(bool,string?)> Delete(int id){var c=await repo.Get(id);if(c==null)return(false,"Cliente no encontrado.");if(await repo.HasOrders(id))return(false,"No se puede eliminar un cliente con órdenes.");repo.Remove(c);await repo.Save();await cache.Remove(AllKey,$"clientes:{id}");return(true,null);} }
public interface IOrdenService {Task<List<OrdenDto>> All();Task<OrdenDto?> Get(int id);Task<List<OrdenDto>> ForClient(int id);Task<(OrdenDto? data,string? error)> Create(OrdenCreateDto d);}
public class OrdenService(IOrdenRepository orders,IClienteRepository clients,ICacheService cache):IOrdenService { const string AllKey="ordenes:all"; static OrdenDto Map(Orden o)=>new(o.Id,o.ClienteId,o.FechaOrden,o.MontoTotal); public async Task<List<OrdenDto>> All(){var v=await cache.Get<List<OrdenDto>>(AllKey);if(v!=null)return v;v=(await orders.All()).Select(Map).ToList();await cache.Set(AllKey,v);return v;} public async Task<OrdenDto?> Get(int id)=>(await orders.Get(id)) is { } o?Map(o):null; public async Task<List<OrdenDto>> ForClient(int id)=>(await orders.ForClient(id)).Select(Map).ToList(); public async Task<(OrdenDto?,string?)> Create(OrdenCreateDto d){if(await clients.Get(d.ClienteId)==null)return(null,"Cliente no encontrado.");var o=new Orden{ClienteId=d.ClienteId,FechaOrden=d.FechaOrden??DateTime.UtcNow,MontoTotal=d.MontoTotal};await orders.Add(o);await orders.Save();await cache.Remove(AllKey,"clientes:all",$"clientes:{d.ClienteId}");return(Map(o),null);} }
